SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for tb_couple
-- ----------------------------
DROP TABLE IF EXISTS `tb_couple`;
CREATE TABLE `tb_couple`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `slug` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一标识 / 占位图文件名',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '情侣名',
  `mark` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '印章单字',
  `chapter` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '篇章',
  `era` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '时代',
  `era_type` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分卷 past / now',
  `relic` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '续缘信物',
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '缘分状态',
  `brief` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '一句话小传',
  `story` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '前尘细说',
  `verse` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '题句',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标签，逗号分隔',
  `image_url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '图片位：后台改这里即可换图',
  `image_slot` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '建议的本地图片路径',
  `sort_no` int NULL DEFAULT 0 COMMENT '排序',
  `enabled` tinyint NULL DEFAULT 1 COMMENT '1 展示 / 0 隐藏',
  `create_time` datetime NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_slug`(`slug` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '苦情树 · 续缘相册' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tb_couple
-- ----------------------------
INSERT INTO `tb_couple` VALUES (1, 'yuehong', '东方月初 × 涂山红红', '月', '月红篇', '五百年前 · 缘之始', 'past', '虚空之泪', '再世续缘 · 以全部妖力为祭', '苦情树下一纸誓约，千古第一陨落之日，正是来生相见之始。', '东方月初幼年为涂山红红所救，为她人妖和平的心愿离开涂山、扬名天下，用尽一生。八十岁那年大战黑狐后，二人在苦情树下立下再世续缘之约：以两眼虚空之泪为匙，以全部妖力与相识的一点一滴为代价。红红自此失去妖力与记忆，化作涂山苏苏；他的一颗泪，随转世成了白月初的右眼。', '千古第一陨落之日，正是来生相见之始。', '虚空之泪,苦情树,纯爱天篇', 'https://ts1.tc.mm.bing.net/th/id/R-C.a5906a1e984803aeacdda67e066b0aff?rik=Z8skfHn%2b%2bZIZCw&riu=http%3a%2f%2fpuui.qpic.cn%2fvpic_cover%2fv3238m0gsgk%2fv3238m0gsgk_hz.jpg%2f1280&ehk=lTJ09vCUWREcgSj%2fHxBYXzmhh37Y0XdsmtleMVJvAlY%3d&risl=&pid=ImgRaw&r=0', '/couples/yuehong.jpg', 1, 1, '2026-11-16 21:11:12', '2026-11-18 00:21:05');
INSERT INTO `tb_couple` VALUES (2, 'baisu', '白月初 × 涂山苏苏', '今', '今生 · 红线仙', '今 生 · 缘 再 续', 'now', '纯爱天篇 / 虚空之泪', '红线相牵 · 故事未竟', '一个想成为真正红线仙的失忆狐妖，一个贪吃、却藏着千古第一之泪的少年。', '失去全部妖力与记忆的涂山红红成了苏苏，东方月初的转世成了白月初。二人被安排成搭档，一桩桩再世续缘的任务里，替别人找回前尘，也一步步走近自己的前世。纯爱天篇、忆梦锤、虚空之泪……红线牵得越长，尽头越是他们自己。', '红线未断，故事仍在继续。', '红线仙,纯爱天篇,今生', 'https://ts2.tc.mm.bing.net/th/id/OIP-C.Wx49nrx5BuRFBI9violxkQHaEK?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', '/couples/baisu.jpg', 2, 1, '2026-11-16 21:11:12', '2026-11-18 00:22:01');
INSERT INTO `tb_couple` VALUES (3, 'xiasha', '梵云飞 × 厉雪扬', '沙', '下沙篇', '今 生 · 第 一 桩 续 缘', 'now', '千年御水珠', '再世续缘 · 终成眷属', '西西域沙狐王子与冰将军，一珠分作两半；求婚九十九次之后，才等来第一百次的相认。', '梵云飞为救厉雪扬吞下专克沙狐的千年御水珠，从此成了不怕水的沙狐；二人相守八十年，军娘病逝后他以御水珠为祭发动转世续缘。转世的半颗珠子埋在厉雪扬体内成了胆结石，害她一直认不出那只「土狗」。苏苏与白月初接下的第一桩任务，便是替他们把这句「对不起我错了」说完。', '求婚百次，只为换她一句记得。', '千年御水珠,冰凌雪枪,下沙篇', 'https://ts4.tc.mm.bing.net/th/id/OIP-C.VuyPSpSM8Srk_AJhWZ-FUgHaDu?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', '/couples/xiasha.jpg', 3, 1, '2026-11-16 21:11:12', '2026-11-18 00:23:09');
INSERT INTO `tb_couple` VALUES (4, 'weisheng', '胡尾生 × 月啼暇', '木', '尾生篇', '今 生 · 抱 柱 之 约', 'now', '七宝妙树皮', '再世续缘 · 误会得解', '一场大雨，一个「她没来」的误会；他抱树而死，却不知怀里那棵树正是她。', '月啼族族长月啼暇是森林的守护精灵，淋雨便会现出树形、动弹不得；与伐木工的前世相约私奔那日天降大雨，尾生苦等不至，抱树溺亡。七宝妙树皮作为续缘之匙长在转世尾生背后，使他一遇雨也化为树。待白月初与苏苏解开误会，二人才终成眷属，一起开了家植物店。', '抱柱之约，原是抱住了她。', '七宝妙树皮,月啼族,尾生篇', 'https://ts2.tc.mm.bing.net/th/id/OIP-C.tqds782K0ygaot9kLrtDdgHaEz?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', '/couples/weisheng.jpg', 4, 1, '2026-11-16 21:11:12', '2026-11-18 00:24:17');
INSERT INTO `tb_couple` VALUES (5, 'wangquan', '王权富贵 × 清瞳', '剑', '王权篇', '前 尘 · 道 门 兵 人', 'past', '王权剑', '再世续缘 · 五百年相寻', '被当作除妖兵器养大的少年，为替一只蜘蛛精看一眼外面的世界，燃尽寿命唤出王权剑意。', '王权富贵持天地一剑，是王权家最锋利的「兵人」；清瞳以蛛丝织成画卷，替足不出户的他描摹道门之外的风景。为护清瞳离开家门，他几乎丧命，死前与她签下再世续缘。清瞳苦寻五百年，找到的转世王富贵早已忘了她，却仍痴心相随。', '剑能斩妖，斩不断一双想看世界的眼。', '王权剑,王权剑意,清瞳', 'data:image/jpeg;base64,', '/couples/wangquan.jpg', 5, 1, '2026-11-16 21:11:12', '2026-11-18 00:32:31');
INSERT INTO `tb_couple` VALUES (6, 'qianyan', '颜如玉 × 律笺文', '颜', '千颜篇', '今 生 · 来 世 相 见', 'now', '天罗地网', '再世续缘 · 记忆被夺', '千面妖容的弟子与第一妖捕，一句「来世相见」，代价是四成妖力与全部记忆。', '空陷山牛鬼颜如玉习得涂山容容的易容术与望月掌，却栽在妖捕律笺文手里。她以卧底之身接近，用问话的方式与他定下续缘契约；续缘提前发动，四成妖力与记忆被黑狐夺去，他成了三尾黑魉，她忘了他。唯有那句「来世相见」，还留在苦情树下。', '我颜如玉，愿意使用四成妖力，让我们来世相见。', '望月掌,天罗地网,黑狐', 'data:image/jpeg;base64,', '/couples/qianyan.jpg', 6, 1, '2026-11-16 21:11:12', '2026-11-18 00:31:29');
INSERT INTO `tb_couple` VALUES (7, 'nanguo', '平丘月初 × 欢都落兰', '蛊', '南国篇', '前 尘 · 另 一 世', 'past', '情蛊 / 紫欢金铃', '再世续缘 · 终得成全', '被当作「东方月初转世」养大的少年，只为证明自己是平丘月初，逃到南国，爱上一位公主。', '平丘月初拒绝入赘涂山，在傲来国三少相助下隐去法力出走，与南国公主欢都落兰相识相爱。落兰以心血饲养情蛊、以返雏毒针换回旧颜，只为让白月初想起那一世。最终在红红的宽容、东方月初的成全与容容的助力下，二人签下再世续缘。', '我不是谁的转世，我只是喜欢你的平丘月初。', '情蛊,紫欢金铃,万毒之体', 'https://ts1.tc.mm.bing.net/th/id/OIP-C.Lc1GuVA9AoDRRZBgG8_bNgHaIn?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', '/couples/nanguo.jpg', 7, 1, '2026-11-16 21:11:12', '2026-11-18 00:33:37');
INSERT INTO `tb_couple` VALUES (8, 'zhuye', '东方淮竹 × 王权霸业', '竹', '竹业篇', '前 尘 · 上 一 代', 'past', '王权剑 / 面具', '未立续缘 · 终生相忆', '面具组织出圈外一战，剑心尽失；上一代未能说尽的遗憾，成了王权富贵那一代的起点。', '王权霸业率「面具」众人踏出圈外，惨败而归、剑心尽碎；东方淮竹因金面火神之祸家破人亡，二人的结合始于一场身不由己。淮竹早逝，霸业终身未再娶，把儿子王权富贵锻造成除妖机器，直到寿终时才抱着剑鞘与玉笛泪流满面。', '淮竹，我终于可以怀着剑心去见你了。', '面具组织,圈外,王权剑意', 'data:image/jpeg;base64,', '/couples/zhuye.jpg', 8, 1, '2026-11-16 21:11:12', '2026-11-18 00:37:52');
INSERT INTO `tb_couple` VALUES (9, 'beishan', '石宽 × 御妖国公主', '北', '月红篇 · 北山', '前 尘 · 北 山 旧 事', 'past', '御妖子母符', '一念之迟 · 错过百年', '一枚御妖子母符，牵着的原是主仆，也是一句始终没能说出口的心意。', '北山妖帝石宽受御妖子母符所缚，与御妖国公主之间的情意被身份与符咒层层遮掩。公主命陨之后，他困在「她是否曾真心」的疑问里苦守多年，直至白月初与苏苏揭开旧事，才知那一世的沉默里，藏着的是护他周全的苦心。', '有些话，一迟便是百年。', '御妖子母符,北山妖帝,月红篇', 'https://kk-promote-template.v3mh.com/answer-admin/prod/image/xjeZp57MB/33-%E5%9B%BE%E7%89%87.jpg', '/couples/beishan.jpg', 9, 1, '2026-11-16 21:11:12', '2026-11-18 00:40:20');
INSERT INTO `tb_couple` VALUES (10, 'jinxi', '木蔑 × 翠玉鸣鸾', '曦', '金晨曦篇', '今 生 · 边 境', 'now', '金晨曦 / 两生花', '前世今生 · 终得相认', '边境沐天城，两生花开处；被改写过的记忆里，仍有人不肯放手。', '金晨曦篇串起沐天城、两生花与边境诸线：木蔑与翠玉鸣鸾的前世今生、金人凤骗取蛭妖换血秘法的旧案，都在同一张大网里收束。记忆可以被夺走、被替换，可苦情树下许过的愿，总会在某个转世的瞬间重新响起。', '线越牵越长，尽头却是重逢。', '金晨曦,两生花,沐天城', 'https://ts2.tc.mm.bing.net/th/id/OIP-C.IJ-GPB9utNyTPKU3MnS0RgHaF2?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', '/couples/jinxi.jpg', 10, 1, '2026-11-16 21:11:12', '2026-11-18 00:41:12');

-- ----------------------------
-- Table structure for tb_treasure
-- ----------------------------
DROP TABLE IF EXISTS `tb_treasure`;
CREATE TABLE `tb_treasure`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `slug` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一标识 / 占位图文件名',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '法宝名',
  `alias` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '别称',
  `mark` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '印章单字',
  `scroll` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分卷 tushan/daomen/xixiyu/nanguo',
  `owner` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '持有者',
  `chapter` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出处篇章',
  `kind` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '类别',
  `power` int NULL DEFAULT 3 COMMENT '灵力 1-5',
  `brief` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '器之用',
  `tale` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '缘之由',
  `verse` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '题句',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标签，逗号分隔',
  `image_url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '图片：路径 / 外链 / base64',
  `sort_no` int NULL DEFAULT 0 COMMENT '排序',
  `enabled` tinyint NULL DEFAULT 1 COMMENT '1 展示 / 0 隐藏',
  `create_time` datetime NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `price` int NULL DEFAULT 5 COMMENT '法宝价格 2-25',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_treasure_slug`(`slug` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '法宝图鉴' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tb_treasure
-- ----------------------------
INSERT INTO `tb_treasure` VALUES (1, 'xukong-zhilei', '虚空之泪', '天地间最强法宝', '泪', 'tushan', '东方月初 → 白月初（右眼）', '月红篇', '续缘 · 空间', 5, '源于至高法力，生于至诚至情。形与寻常眼球无异，却能穿破一切物体、将所触之物移入虚空之境，所到之处时空错乱。', '五百年前东方月初垂死之际因悔恨炼出两颗：一颗被黑狐女王夺走，一颗作为与涂山红红再世续缘之匙，随转世化作白月初的右眼。', '一眼成泪，虚空为此错乱。', '最强法宝,续缘之匙,时空', '/treasures/xukong-zhilei.svg', 10, 1, '2026-11-18 00:58:07', '2026-11-18 01:24:56', 2);
INSERT INTO `tb_treasure` VALUES (2, 'chunai-tianpian', '纯爱天篇', '狐妖天书 · 红娘秘籍', '书', 'tushan', '涂山红红 → 涂山苏苏', '全篇', '天书 · 辅佐', 4, '苦情巨树的树浆化纸而成，与苦情树心灵相通，能感知树下许愿之人的相爱往事，显出关键提示；刀枪不入，是红线仙完成任务的不二帮手。', '书名由东方月初亲手题给红红，已逾八百年。每位狐妖一生只有唯一一本天书，此书曾为虚空之泪所破，现归苏苏所有。', '树浆为纸，写尽世间未了情。', '天书,红线仙,苦情树', '/treasures/chunai-tianpian.svg', 20, 1, '2026-11-18 00:58:07', NULL, 3);
INSERT INTO `tb_treasure` VALUES (3, 'yimeng-chui', '忆梦锤', '续缘三宝之一', '锤', 'tushan', '涂山红线仙', '全篇', '续缘 · 记忆', 3, '传为女娲补天炼石之柴火木所制，形似寻常木锤，锤身印涂山徽标。注入狐妖妖力敲击续缘二人头部，便可唤回前世相爱的记忆。', '售价五十万，是转世续缘中唤醒记忆的必备道具。涂山容容曾以此敲回东方月初与王权富贵的前世记忆。', '一锤轻落，前世如梦初醒。', '记忆,续缘,涂山道具', '/treasures/yimeng-chui.svg', 30, 1, '2026-11-18 00:58:07', NULL, 4);
INSERT INTO `tb_treasure` VALUES (4, 'wujin-jiuhu', '无尽酒葫', '无尽酒壶', '酒', 'tushan', '涂山雅雅', '月红篇', '空间 · 增力', 4, '空间法宝，葫中酒液无穷无尽。雅雅饮下后妖力大增，九尾天狐那令群妖闻风丧胆的最强状态，正由饮酒而生。', '雅雅常年将酒葫系于腰间，护涂山、战黑狐之际，往往先饮一口，再以绝对零域冻住对手。', '一葫未尽，九尾已临。', '空间法宝,妖力,九尾天狐', '/treasures/wujin-jiuhu.svg', 40, 1, '2026-11-18 00:58:07', NULL, 5);
INSERT INTO `tb_treasure` VALUES (5, 'jiuzhuan-xuanyinshui', '九转玄阴水', '涂山独门', '阴', 'tushan', '涂山狐妖', '全篇', '独门 · 克制', 3, '涂山狐妖独门法宝，至阴至寒，专克白月初的灭妖神火「纯质阳炎」——阴阳相对，正是涂山为制衡东方灵族所留。', '此水不尚攻伐，唯以相克见长，常见于涂山与一气道盟相互牵制的旧事之中。', '至阴一泓，可熄至阳之焰。', '相克,纯质阳炎,涂山', '/treasures/jiuzhuan-xuanyinshui.svg', 50, 1, '2026-11-18 00:58:07', NULL, 6);
INSERT INTO `tb_treasure` VALUES (6, 'jueyuan-zhizhua', '绝缘之爪', '非法器 · 天赋异能', '爪', 'tushan', '涂山红红 / 涂山苏苏', '月红篇', '异能 · 克器', 5, '并非器物，而是与生俱来的天赋：双手免疫一切法宝，可徒手擒下虚空之泪、操控纯质阳炎，连没有实体的黑狐也能抓住。', '红红以全部妖力和记忆为代价化作苏苏后，法力尽失，唯独这双手仍能接下天下法器。', '万器皆可被执，唯情不可。', '异能,克一切法宝,涂山红红', '/treasures/jueyuan-zhizhua.svg', 60, 1, '2026-11-18 00:58:07', NULL, 7);
INSERT INTO `tb_treasure` VALUES (7, 'kuqing-shu', '苦情树', '续缘之根 · 圣物', '树', 'tushan', '涂山', '全篇', '圣物 · 续缘', 5, '生长于涂山的巨树，花如蒲公英。人与妖在树下起誓，以相爱的记忆与部分妖力为祭封入法宝，再由狐妖一分为二，方得再世续缘。', '它不是器物，而是天下续缘法宝的缘起；天书以它的树浆为纸，红线仙因它的许愿而奔走。', '花开如雪，落处皆是来生。', '圣物,再世续缘,涂山', '/treasures/kuqing-shu.svg', 70, 1, '2026-11-18 00:58:07', NULL, 9);
INSERT INTO `tb_treasure` VALUES (8, 'wangquan-jian', '王权剑', '天地一剑', '剑', 'daomen', '王权富贵 → 白裘恩', '王权篇', '攻伐 · 先天灵宝', 5, '人类发现的第一件法宝，天生灵物，剑柄上方书「王权」二字，为天地一剑王权世家所有，众妖闻之畏惧。', '王权富贵曾持此剑斩妖无数，后为护清瞳以自身寿命唤剑；此剑辗转之后，竟被白裘恩当作废铁按斤收着。', '剑上二字，压尽天下妖名。', '先天灵宝,王权世家,兵人', '/treasures/wangquan-jian.svg', 80, 1, '2026-11-18 00:58:07', NULL, 10);
INSERT INTO `tb_treasure` VALUES (9, 'chunzhi-yangyan', '纯质阳炎', '灭妖神火', '炎', 'daomen', '东方灵族 / 东方月初 / 白月初', '月红篇', '神火 · 灭妖', 5, '东方灵族独门「灭妖神火」，专克妖怪，唯有天生灵力的东方血脉可以驱用。严格说是血脉绝技，因威名列于器谱。', '东方月初曾在涂山废弃仓库留下一大团阳炎，只需简单召唤术便可取用；百年后其转世白月初同样运用自如。', '火起东方，妖气尽退。', '神火,东方灵族,绝技', '/treasures/chunzhi-yangyan.svg', 90, 1, '2026-11-18 00:58:07', NULL, 11);
INSERT INTO `tb_treasure` VALUES (10, 'zhuizong-fu', '追踪符', '瞬移符箓', '符', 'daomen', '一气道盟', '全篇', '符箓 · 瞬移', 2, '形如寻常符纸，注入法力便可瞬息抵达目标所在之处，但须持有目标的一件物品为引，且一张所费不菲。', '红娘任务里赶赴续缘之地的常用之物，与忆梦锤同属「好用但很贵」的涂山与道门道具。', '一符既焚，山海不隔。', '符箓,瞬移,道具', '/treasures/zhuizong-fu.svg', 100, 1, '2026-11-18 00:58:07', NULL, 12);
INSERT INTO `tb_treasure` VALUES (11, 'zhengshen-huashen', '正神化身', '道门降神之器', '神', 'daomen', '一气道盟道门', '全篇', '召唤 · 攻伐', 3, '道门法宝，可召唤出一尊体型巨大的神祇与敌对阵，威势浩大，正面交锋时尤为难挡。', '与王权剑一脉的人间法器同源，皆是人类借法宝之力与妖相抗的凭据。', '神影一现，天地为之俯首。', '召唤,道门,攻伐', '/treasures/zhengshen-huashen.svg', 110, 1, '2026-11-18 00:58:07', NULL, 13);
INSERT INTO `tb_treasure` VALUES (12, 'wujin-shalou', '无尽沙漏', '袖里乾坤', '沙', 'daomen', '道门', '全篇', '空间 · 收纳', 3, '空间法宝，内藏约五公里的独立天地，可纳物、可藏身，威力强、用处极广。', '与涂山无尽酒葫同为空间类法宝，一藏天地、一藏酒液，皆以「无尽」为名。', '一粒沙中，另有一段光阴。', '空间法宝,收纳,道门', '/treasures/wujin-shalou.svg', 120, 1, '2026-11-18 00:58:07', NULL, 14);
INSERT INTO `tb_treasure` VALUES (13, 'tianluo-diwang', '天罗地网', '妖捕之器', '网', 'daomen', '律笺文', '颜如玉篇', '擒缚 · 阵', 3, '妖捕律笺文所持法宝，撒之成阵，专用于缉拿大妖，是人间捕妖一脉最倚重的束缚之器。', '她以卧底之身接近颜如玉，最终却用智慧问出了那句续缘之约，此网终究没能网住自己的心。', '网可缚妖，缚不住一眼动心。', '擒缚,妖捕,颜如玉篇', '/treasures/tianluo-diwang.svg', 130, 1, '2026-11-18 00:58:07', NULL, 15);
INSERT INTO `tb_treasure` VALUES (14, 'yuyao-zimufu', '御妖子母符', '御妖国禁制', '御', 'daomen', '御妖国', '北山篇', '符箓 · 禁制', 3, '御妖国先祖所创：子符令妖吞下，母符一毁则妖元尽毁；母符虽存，若不年年服解药亦痛楚难当。', '正是这道符令万妖为奴，也酿成御妖国公主与北山妖帝石宽那段未能说尽的缘。', '一符在手，万妖俯首；一心难求。', '禁制,御妖国,石宽', '/treasures/yuyao-zimufu.svg', 140, 1, '2026-11-18 00:58:07', NULL, 16);
INSERT INTO `tb_treasure` VALUES (15, 'sixiang-jing', '四象镜', '式神之镜', '镜', 'daomen', '道门 / 金风岭', '全篇', '召唤 · 式神', 3, '可召唤朱雀、青龙等四象式神：朱雀擅火，青龙擅水，显现为性格鲜明的人形，召唤各有其代价。', '式神出镜，代价却往往只是些出人意料的俗世琐事，是道门法宝里最不肃穆的一件。', '镜开四象，各有其价。', '式神,召唤,道门', '/treasures/sixiang-jing.svg', 150, 1, '2026-11-18 00:58:07', NULL, 17);
INSERT INTO `tb_treasure` VALUES (16, 'qiannian-yushuizhu', '千年御水珠', '续缘之匙', '珠', 'xixiyu', '梵云飞 / 厉雪扬', '下沙篇', '续缘 · 御水', 4, '蓝色宝珠，存世千年以上，可在一定范围内御使水元素；本为专克沙狐一族的护身法宝。', '梵云飞为救厉雪扬吞下此珠，从此成了不怕水的沙狐；后一分为二作二人再世续缘之匙，半颗竟化作转世军娘体内的胆结石。', '一珠分两半，生死各执其一。', '续缘之匙,御水,下沙篇', '/treasures/qiannian-yushuizhu.svg', 160, 1, '2026-11-18 00:58:07', NULL, 18);
INSERT INTO `tb_treasure` VALUES (17, 'bingling-xueqiang', '冰凌雪枪', '千年寒冰戈', '冰', 'xixiyu', '厉雪扬（冰将军）', '下沙篇', '攻伐 · 冰', 4, '冰将军厉雪扬的兵器，寒气极盛，遇水成冰，可冻住千年妖祸；漫画中称「千年寒冰戈」，动画作冰凌雪枪。', '她曾持此枪孤身斩杀火妖，被梵云飞救下，才有了那第一百次求婚。', '枪出成雪，一怒可封千里。', '冰系,攻伐,厉雪扬', '/treasures/bingling-xueqiang.svg', 170, 1, '2026-11-18 00:58:07', NULL, 20);
INSERT INTO `tb_treasure` VALUES (18, 'qibao-miaoshupi', '七宝妙树皮', '续缘之匙', '木', 'xixiyu', '月啼暇 / 胡尾生', '尾生篇', '续缘 · 御木', 4, '月啼族族长月啼暇的至宝，可操控一切植物；曾生长在胡尾生背后，使他一淋雨便化作树木。', '尾生抱树而死的误会，正因月啼暇淋雨现出树形、不能移动；待二人误会解开、续缘功成，树皮方被收回。', '抱柱之约，原是抱住了她。', '续缘之匙,御木,尾生篇', '/treasures/qibao-miaoshupi.svg', 180, 1, '2026-11-18 00:58:07', NULL, 21);
INSERT INTO `tb_treasure` VALUES (19, 'zihuan-jinling', '紫欢金铃', '南国皇室至宝', '铃', 'nanguo', '欢都一族 / 欢都落兰', '南国篇', '音波 · 毒', 4, '南国皇室欢都一族的法宝，唯有炼成万毒之体者方可持有；配合音波毒功，可凝音波为震波针承载神经毒素，无形无质、百发百中。', '后作为转世续缘的法宝，被见钱眼开的白裘恩顺手取走，成了南国篇里最令人哭笑不得的一笔。', '铃响无声，毒已入神。', '万毒之体,音波毒功,续缘法宝', '/treasures/zihuan-jinling.svg', 190, 1, '2026-11-18 00:58:07', NULL, 22);
INSERT INTO `tb_treasure` VALUES (20, 'fanchu-duzhen', '返雏毒针', '返老还童之针', '针', 'nanguo', '欢都落兰', '南国篇', '毒 · 返雏', 3, '黑狐所予之毒与南国公主飞针相合而成。此针不向敌人，而是扎入自己体内，令毒液回流，使身体恢复至从前的状态。', '以己身为炉，只为换回能与心上人相认的模样，是南国毒术里最温柔也最狠的一种。', '针针向己，只为旧颜如初。', '毒针,返雏,落兰', '/treasures/fanchu-duzhen.svg', 200, 1, '2026-11-18 00:58:07', NULL, 23);
INSERT INTO `tb_treasure` VALUES (21, 'qinggu', '情蛊', '南国痴心蛊', '蛊', 'nanguo', '南国女子', '南国篇', '蛊术 · 情', 3, '南国姑娘求而不得时，择良地种下一枚蛊，日日以心血与妖气为饲，祈求能与心仪之人长相厮守。', '落兰为平丘月初种下的，正是这一枚痴心；蛊由情生，也因情而难解。', '心血饲蛊，只愿一人回头。', '蛊术,痴情,南国', '/treasures/qinggu.svg', 210, 1, '2026-11-18 00:58:07', NULL, 24);
INSERT INTO `tb_treasure` VALUES (22, 'zixinghe-shuijing', '紫星河水晶', '南国洞顶之晶', '晶', 'nanguo', '南国', '南国篇', '阵 · 阴气', 3, '南国特产，体积庞大，镶嵌于洞穴顶部，通体透明泛紫。月光照射之下四周阴气大盛，配合黑狐之泪可强行抽出灵魂。', '阴气与情蛊、毒功同为南国一脉的根基，也曾在平丘月初那一世搅动生死。', '紫光满洞，月色亦可夺魂。', '阴气,阵法,黑狐之泪', '/treasures/zixinghe-shuijing.svg', 220, 1, '2026-11-18 00:58:07', NULL, 25);

-- ----------------------------
-- Table structure for tb_user
-- ----------------------------
DROP TABLE IF EXISTS `tb_user`;
CREATE TABLE `tb_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户名（道号）',
  `password` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '密码（MD5 加盐加密后存储）',
  `race` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '种族：人 / 妖',
  `gender` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '性别：男 / 女',
  `avatar` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '头像（前端压缩后的 base64 data URL）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '注册时间',
  `permission` tinyint NULL DEFAULT 1 COMMENT '权限：1 普通用户 / 0 管理员',
  `gold` int NOT NULL DEFAULT 0 COMMENT '金币数量：拈签消耗/领金增加，后台可管理',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户表' ROW_FORMAT = DYNAMIC;

