-- ----------------------------
-- Table structure for tb_user_couple
-- ----------------------------
DROP TABLE IF EXISTS `tb_user_couple`;
CREATE TABLE `tb_user_couple`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `slug` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一标识 / 占位图文件名',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '情侣名',
  `mark` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '印章单字',
  `chapter` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出处 / 篇章',
  `era` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '时代描述',
  `relic` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '续缘信物',
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '缘分状态',
  `brief` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '一句话小传',
  `story` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '故事细说',
  `verse` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '题句',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标签，逗号分隔',
  `image_url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '图片位：路径 / 外链 / base64',
  `image_slot` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '建议的本地图片路径',
  `contributor` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '投稿人道号',
  `enabled` tinyint NULL DEFAULT 1 COMMENT '1 展示 / 0 隐藏',
  `create_time` datetime NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `delete_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '投稿人自助删除令牌',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_slug`(`slug` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '苦情树 · 我的小情侣（用户共享投稿）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tb_user_couple
-- ----------------------------
INSERT INTO `tb_user_couple` VALUES (8, 'u_7995242b2d09', '米苏', NULL, '异形舞台', NULL, NULL, NULL, NULL, NULL, '“我的神，我的宇宙”', NULL, 'https://ts1.tc.mm.bing.net/th/id/OIP-C.86qRSVUWxPrIhbAcgBBgTwHaEJ?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', NULL, '渔舟唱晚', 1, '2026-11-16 23:00:45', NULL, '8a6c70dfe5eb49bba4a667a1eb25390fcc1ba3dc808a4e43');
INSERT INTO `tb_user_couple` VALUES (9, 'u_1a9d8c8a959d', '少微', NULL, '紫罗兰永恒花园', NULL, NULL, NULL, NULL, NULL, '', NULL, 'https://ts1.tc.mm.bing.net/th/id/OIP-C.UodcqA3850pTgxS1xeyUDAAAAA?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', NULL, '渔舟唱晚', 1, '2026-11-16 23:06:21', NULL, '862d02a9a298426ebd243e43ad12d0b90b08c450206c45c2');
INSERT INTO `tb_user_couple` VALUES (10, 'u_4ab945f40018', '艾笠', NULL, '进击的巨人', NULL, NULL, NULL, NULL, NULL, '', NULL, 'https://ts2.tc.mm.bing.net/th/id/OIP-C.YDAcMxwE-juIQYsn2SRelgAAAA?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', NULL, '渔舟唱晚', 1, '2026-11-18 01:21:11', NULL, 'b1963e75fc4f44b1b51a6498ec1e64c0f8ac7904c8c34986');
INSERT INTO `tb_user_couple` VALUES (11, 'u_aa26beb08bf0', '蓝玖', NULL, '降灵记', NULL, NULL, NULL, NULL, NULL, '一夜白头', NULL, 'https://ts1.tc.mm.bing.net/th/id/OIP-C.9jCDJiUNp4M-nXiYsWFE7AHaEK?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', NULL, '渔舟唱晚', 1, '2026-11-18 01:25:49', NULL, 'fe21d3061be2492083a887dffd6bed261df3a62b0a344032');
INSERT INTO `tb_user_couple` VALUES (12, 'u_abfca8382a6c', '堀宫', NULL, '堀与宫村', NULL, NULL, NULL, NULL, NULL, '', NULL, 'https://ts1.tc.mm.bing.net/th/id/OIP-C.g6HsBsmkXbT-My-YDqOFfgHaIk?r=0&rs=1&pid=ImgDetMain&o=7&rm=3', NULL, 'ljh', 1, '2026-11-18 01:31:09', NULL, '5e7e77d3d4084fcc9d77dbf48807d685d772ad1826544607');

SET FOREIGN_KEY_CHECKS = 1;
